INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6359173, 941763, 108069, '<td valign="top">Great abstract. having them positioned as they are and not all perfectly symmetrical really adds life and character to the shot. Great art piece.</td>', 'Great abstract. having them positioned as they are and not all perfectly symmetrical really adds life and character to the shot. Great art piece.', '2011-03-21 18:24:39.000000', NULL, 1),
(6359175, 941838, 108069, '<td valign="top">Rich color, very sharp. Nice photo.</td>', 'Rich color, very sharp. Nice photo.', '2011-03-21 18:26:08.000000', NULL, 1),
(6359177, 941710, 108069, '<td valign="top">Nice depth. Really varied scenery and cloud formations. Great photo.</td>', 'Nice depth. Really varied scenery and cloud formations. Great photo.', '2011-03-21 18:26:58.000000', NULL, 1),
(6359179, 941805, 15711, '<td valign="top">Stunning on all counts.  A DPC type image without at all being cliche.  I love it. 8</td>', 'Stunning on all counts.  A DPC type image without at all being cliche.  I love it. 8', '2011-03-21 18:27:33.000000', NULL, 1),
(6359181, 941704, 108069, '<td valign="top">Great focal point. Spot on. Rich and vibrant yet soothing colors. Great photo.</td>', 'Great focal point. Spot on. Rich and vibrant yet soothing colors. Great photo.', '2011-03-21 18:27:59.000000', NULL, 1),
(6359182, 941118, 15711, '<td valign="top">Terrific  You just can''t go wrong with a silhouette, a beach and a sunset.  She''s some kind of limber!  :)</td>', 'Terrific  You just can''t go wrong with a silhouette, a beach and a sunset.  She''s some kind of limber!  :)', '2011-03-21 18:28:05.000000', NULL, 1),
(6359183, 941510, 15711, '<td valign="top">This is really beautiful.  Something so compelling yet classic about lighthouses.</td>', 'This is really beautiful.  Something so compelling yet classic about lighthouses.', '2011-03-21 18:28:33.000000', NULL, 1),
(6359185, 941448, 15711, '<td valign="top">HAHAHA  Aimee has incredible eyelashes!  This is clever and not at all expected.  You always ace the portraits.  Nice going.</td>', 'HAHAHA  Aimee has incredible eyelashes!  This is clever and not at all expected.  You always ace the portraits.  Nice going.', '2011-03-21 18:28:44.000000', NULL, 1),
(6359187, 941604, 15711, '<td valign="top">This takes the cliche glass and pumps it up a notch I really like it.  Trying to figure out how you did it.  Nice one. 7</td>', 'This takes the cliche glass and pumps it up a notch I really like it.  Trying to figure out how you did it.  Nice one. 7', '2011-03-21 18:29:13.000000', NULL, 1),
(6359188, 941327, 15711, '<td valign="top">Terrific kitty portrait.  Love the whiskers.</td>', 'Terrific kitty portrait.  Love the whiskers.', '2011-03-21 18:29:17.000000', NULL, 1),
(6359189, 941495, 15711, '<td valign="top">This is really good. Love the reflection, the light trail and the colors.  But most of all.... the tilt.  Nice one!!</td>', 'This is really good. Love the reflection, the light trail and the colors.  But most of all.... the tilt.  Nice one!!', '2011-03-21 18:29:40.000000', NULL, 1),
(6359190, 941037, 15711, '<td valign="top">What a lovely scene!!</td>', 'What a lovely scene!!', '2011-03-21 18:29:45.000000', NULL, 1),
(6359191, 941750, 15711, '<td valign="top">WOW - how many times did you have to do THAT??  Nice stop action.</td>', 'WOW - how many times did you have to do THAT??  Nice stop action.', '2011-03-21 18:29:49.000000', NULL, 1),
(6359192, 941523, 15711, '<td valign="top">OMG!!!  Look at that precious puppy.  hee hee Optimally, he would have been looking at the camera, but still.  I LOVE IT.</td>', 'OMG!!!  Look at that precious puppy.  hee hee Optimally, he would have been looking at the camera, but still.  I LOVE IT.', '2011-03-21 18:30:00.000000', NULL, 1),
(6359193, 941299, 108069, '<td valign="top">Wow, this is a heck of a vantage point. Nicely done. Well exposed with nothing blown out; nice tonal range. Great photo.</td>', 'Wow, this is a heck of a vantage point. Nicely done. Well exposed with nothing blown out; nice tonal range. Great photo.', '2011-03-21 18:30:27.000000', NULL, 1),
(6359194, 941030, 15711, '<td valign="top">ROFL  Hate it that you guys are so shy in front of the camera.  HA HA HA HA</td>', 'ROFL  Hate it that you guys are so shy in front of the camera.  HA HA HA HA', '2011-03-21 18:30:29.000000', NULL, 1),
(6359195, 941522, 15711, '<td valign="top">This is just lovely.  Great narrow DOF.  The colors - like sherbet.</td>', 'This is just lovely.  Great narrow DOF.  The colors - like sherbet.', '2011-03-21 18:30:41.000000', NULL, 1),
(6359197, 941164, 15711, '<td valign="top">I keep coming back to this.  I predict a blue for you yet if it were my nitpick, I might say I wish we could either see her profile or more of her face.  The sky, the wind, the blue/gray and the rich brown with her white flowing dress is pretty spectacular.  I bet it would have knock out impact BIG on a canvas.</td>', 'I keep coming back to this.  I predict a blue for you yet if it were my nitpick, I might say I wish we could either see her profile or more of her face.  The sky, the wind, the blue/gray and the rich brown with her white flowing dress is pretty spectacular.  I bet it would have knock out impact BIG on a canvas.', '2011-03-21 18:33:11.000000', NULL, 1),
(6359198, 941729, 15711, '<td valign="top">This is mesmerizing with it''s undulating sandy trails created by the tide.  I love how the clouds mimic them.</td>', 'This is mesmerizing with it''s undulating sandy trails created by the tide.  I love how the clouds mimic them.', '2011-03-21 18:33:42.000000', NULL, 1),
